// Frozen map from the positional editor keys of build e5592bc, the last build
// that numbered nodes by position, to the signature keys of its contract nodes.
//
//   node scripts/legacy-keys.mjs <e5592bc checkout> [retained project.json ...]
//
// Run once, by hand. It writes src/cms/legacy-keys.json, which is committed and
// never regenerated by the build: a later template edit must not change it.
// The map is a function of the e5592bc build only. Every given retained project
// must give each contract node the same key through the map as through
// rekeyHtml, or nothing is written.
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { parseFragment, serialize } from 'parse5';
import { preparePage, rekeyHtml, migrateKeys } from '../src/cms/validation.mjs';
import { refreshDevelopersPage } from '../src/cms/legacy-project.mjs';
import { attribute, walk } from '../src/cms/html-tree.mjs';

export const LEGACY_BUILD = 'e5592bc';
const OUTPUT = 'src/cms/legacy-keys.json';

// e5592bc numbering (its validation.mjs:97-103): every element in document
// order gets n<index>, except the SKIFT links, which hold fixed keys and take no
// number. noscript children count: preparePage parses without scripting.
// Takes prepared body HTML and returns it with the keys that build wrote.
export function positionalKeys(html) {
  const tree = parseFragment(html, { scriptingEnabled: false });
  let index = 0;
  walk(tree, node => {
    if (!node.tagName) return;
    const key = attribute(node, 'data-skift-link') !== undefined ? 'skift-nav' : attribute(node, 'data-skift-mobile-link') !== undefined ? 'skift-nav-mobile' : `n${index++}`;
    const item = node.attrs.find(a => a.name === 'data-cms-node');
    if (item) item.value = key; else node.attrs.push({ name: 'data-cms-node', value: key });
  });
  return serialize(tree);
}

const elementsOf = html => { const nodes = []; walk(parseFragment(html, { scriptingEnabled: false }), node => { if (node.tagName) nodes.push(node); }); return nodes; };
const contractKeys = contracts => new Set(contracts.flatMap(contract => [contract.key, contract.spanKey].filter(Boolean)));
function fail(message) { throw new Error(`legacy-keys: ${message}`); }

// The documents of that build, chosen as its scripts/build-cms.mjs:42-43 chose
// them: one per route (noindex pages use 404.html), plus the generated blank.
async function legacyDocuments(root) {
  const module = path => import(pathToFileURL(resolve(root, path)).href);
  const [{ preparePage: legacyPrepare }, { routes }, { layout }] = await Promise.all([module('src/cms/validation.mjs'), module('src/content/site.mjs'), module('src/templates/layout.mjs')]);
  const documents = await Promise.all(routes.map(async page => [page.template, await readFile(resolve(root, page.noindex ? 'dist/404.html' : `dist${page.path}index.html`), 'utf8')]));
  // The asset paths only reach head links; preparePage keys the body.
  documents.push(['blank', layout({ path: '/ny-sida/', name: 'Ny sida', title: 'Ny sida', description: 'En ny idé.', template: 'custom' }, '<section class="section-wrap" style="padding-block:80px;min-height:560px"><span class="eyebrow">EN NY IDÉ</span><h1>Här börjar något.</h1><p>Dubbelklicka för att skriva din berättelse.</p></section>', { css: '/assets/home.css', main: '/assets/main.js' })]);
  return { legacyPrepare, documents };
}

// Pair the two keyings of one document node by node and keep the contract nodes.
function definitionMap(id, document, legacyPrepare) {
  const legacy = legacyPrepare(document), current = preparePage(document);
  if (positionalKeys(current.html) !== legacy.html) fail(`${id}: positionalKeys does not reproduce the ${LEGACY_BUILD} HTML.`);
  const before = elementsOf(legacy.html), after = elementsOf(current.html), keys = contractKeys(current.contracts);
  if (before.length !== after.length || before.some((node, index) => node.tagName !== after[index].tagName)) fail(`${id}: the two keyings do not pair node by node.`);
  const map = {};
  before.forEach((node, index) => {
    const next = attribute(after[index], 'data-cms-node');
    if (keys.has(next)) map[attribute(node, 'data-cms-node')] = next;
  });
  const values = Object.values(map);
  if (values.length !== keys.size || new Set(values).size !== keys.size) fail(`${id}: every contract key must come from exactly one positional key.`);
  return { map, current };
}

const own = (table, key) => typeof key === 'string' && Object.hasOwn(table, key) ? table[key] : undefined;
const nodeKeys = html => { const keys = []; walk(parseFragment(html, { scriptingEnabled: true }), node => { if (node.tagName) keys.push(attribute(node, 'data-cms-node') ?? null); }); return keys; };

// Retained data is re-keyed by rekeyHtml on read. Client copies of the same
// pages go through the map: both must put each contract key on the same node.
function verifyRetained(file, project, legacy, definitions) {
  const developers = definitions.pages.developers;
  for (const raw of project.pages) {
    const page = developers ? refreshDevelopersPage(raw, { id: 'developers', html: developers.html }) : raw;
    const keys = contractKeys((own(definitions.pages, page.id) ?? own(definitions.pages, page.sourceId) ?? definitions.blank).contracts);
    const view = list => list.map(key => keys.has(key) ? key : null);
    const mapped = nodeKeys(migrateKeys({ pages: [page] }, legacy).pages[0].html), rekeyed = nodeKeys(rekeyHtml(page.html));
    if (!isDeepStrictEqual(view(mapped), view(rekeyed))) fail(`${file} ${page.path}: the map and rekeyHtml disagree on a contract node.`);
  }
  console.log(`${file}: ${project.pages.length} pages agree.`);
}

async function main([root, ...retained]) {
  if (!root) fail('usage: node scripts/legacy-keys.mjs <e5592bc checkout> [retained project.json ...]');
  const { legacyPrepare, documents } = await legacyDocuments(root);
  const legacy = { build: LEGACY_BUILD, pages: {}, blank: {} }, definitions = { pages: {}, blank: null };
  for (const [id, document] of documents) {
    const { map, current } = definitionMap(id, document, legacyPrepare);
    if (id === 'blank') { legacy.blank = map; definitions.blank = current; }
    else { legacy.pages[id] = map; definitions.pages[id] = current; }
  }
  for (const file of retained) verifyRetained(file, JSON.parse(await readFile(file, 'utf8')), legacy, definitions);
  await writeFile(OUTPUT, JSON.stringify(legacy, null, 2) + '\n');
  const pairs = [...Object.values(legacy.pages), legacy.blank].reduce((total, map) => total + Object.keys(map).length, 0);
  console.log(`${OUTPUT}: ${Object.keys(legacy.pages).length} pages + blank, ${pairs} pairs.`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) await main(process.argv.slice(2));
